// OdpsParserInit initializes any static state used to implement OdpsParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewOdpsParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func OdpsParserInit() {
	staticData := &OdpsParserParserStaticData
	staticData.once.Do(odpsparserParserInit)
}

// NewOdpsParser produces a new parser instance for the optional input antlr.TokenStream.
func NewOdpsParser(input antlr.TokenStream) *OdpsParser {
	OdpsParserInit()
	this := new(OdpsParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &OdpsParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "OdpsParser.g4"

	return this
}

